// PayrollServiceServer is the server API for PayrollService service.
// All implementations must embed UnimplementedPayrollServiceServer
// for forward compatibility.
type PayrollServiceServer interface {
	GetPayrollSettings(context.Context, *emptypb.Empty) (*PayrollSettings, error)
	UpdatePayrollSettings(context.Context, *PayrollSettings) (*PayrollSettings, error)
	ListSalaries(context.Context, *ListSalariesRequest) (*ListSalariesResponse, error)
	// A new salary version: the previous active one ends.
	CreateSalary(context.Context, *SalaryInput) (*Salary, error)
	UpdateSalary(context.Context, *UpdateSalaryRequest) (*Salary, error)
	DeactivateSalary(context.Context, *SalaryRequest) (*emptypb.Empty, error)
	ListPayrollRuns(context.Context, *ListPayrollRunsRequest) (*ListPayrollRunsResponse, error)
	CreatePayrollRun(context.Context, *CreatePayrollRunRequest) (*PayrollRun, error)
	GetPayrollRun(context.Context, *PayrollRunRequest) (*PayrollRunDetail, error)
	// draft or calculated runs: recalculates every active employee.
	CalculatePayrollRun(context.Context, *CalculatePayrollRunRequest) (*CalculatePayrollRunResponse, error)
	ApprovePayrollRun(context.Context, *PayrollRunRequest) (*PayrollRun, error)
	// approved -> paid: settles loan installments and publishes
	// white.hr.payroll.paid.
	MarkPayrollRunPaid(context.Context, *MarkPayrollRunPaidRequest) (*MarkPayrollRunPaidResponse, error)
	DeletePayrollRun(context.Context, *PayrollRunRequest) (*emptypb.Empty, error)
	ListPayslips(context.Context, *ListPayslipsRequest) (*ListPayslipsResponse, error)
	GetPayslipPdf(context.Context, *PayslipRequest) (*FileBytes, error)
	// One-off taxable additions (bonus, incentive) paid with a period's run.
	ListPayrollAdditions(context.Context, *ListPayrollAdditionsRequest) (*ListPayrollAdditionsResponse, error)
	CreatePayrollAddition(context.Context, *PayrollAdditionInput) (*PayrollAddition, error)
	DeletePayrollAddition(context.Context, *PayrollAdditionRequest) (*emptypb.Empty, error)
	// hr.payroll or hr.approve: everyone's; otherwise own loans.
	ListLoans(context.Context, *ListLoansRequest) (*ListLoansResponse, error)
	GetLoan(context.Context, *LoanRequest) (*Loan, error)
	// self.service for oneself (interest free); hr.payroll for anyone.
	CreateLoan(context.Context, *CreateLoanRequest) (*Loan, error)
	DecideLoan(context.Context, *DecideLoanRequest) (*Loan, error)
	// Pending loans only: hr.payroll or hr.approve for any loan, the borrower
	// for their own. Approved loans are repaid through payroll instead.
	CancelLoan(context.Context, *LoanRequest) (*Loan, error)
	mustEmbedUnimplementedPayrollServiceServer()
}

